@if($page==='purchase_form' && $editable)<script>
const purchaseLines = document.getElementById('purchaseLines');
let purchaseLineIndex = purchaseLines.querySelectorAll('.purchase-line').length;
document.getElementById('addPurchaseLine')?.addEventListener('click', function () {
    const newLine = purchaseLines.querySelector('.purchase-line').cloneNode(true);
    newLine.querySelectorAll('select,input').forEach(function (field) {
        field.name = field.name.replace(/items\[\d+\]/, 'items[' + purchaseLineIndex + ']');
        if (field.tagName === 'SELECT') { field.selectedIndex = 0; } else { field.value = field.name.endsWith('[quantity]') ? 1 : ''; }
    });
    purchaseLines.appendChild(newLine);
    purchaseLineIndex++;
});
purchaseLines.addEventListener('click', function (event) {
    if (event.target.matches('.remove-line') && purchaseLines.querySelectorAll('.purchase-line').length > 1) { event.target.closest('.purchase-line').remove(); }
    updatePurchaseTotals();
});
function updatePurchaseTotals() {
    let total = 0;
    purchaseLines.querySelectorAll('.purchase-line').forEach(function (line) {
        const quantity = Number(line.querySelector('input[name$="[quantity]"]').value || 0);
        const unitCost = Number(line.querySelector('input[name$="[unit_cost]"]').value || 0);
        const lineTotal = quantity * unitCost;
        line.querySelector('.document-line-total').textContent = lineTotal.toFixed(2);
        total += lineTotal;
    });
    document.getElementById('purchaseGrandTotal').textContent = total.toFixed(2);
}
purchaseLines.addEventListener('input', updatePurchaseTotals);
updatePurchaseTotals();
</script>@endif
@if($page==='invoice_form' && $editable)<script>
const invoiceLines = document.getElementById('invoiceLines');
const invoiceAddButton = document.getElementById('addInvoiceLine');
let invoiceLineIndex = invoiceLines ? invoiceLines.querySelectorAll('.invoice-line').length : 0;
invoiceAddButton?.addEventListener('click', function () {
    const newLine = invoiceLines.querySelector('.invoice-line').cloneNode(true);
    newLine.querySelectorAll('select,input').forEach(function (field) {
        field.name = field.name.replace(/items\[\d+\]/, 'items[' + invoiceLineIndex + ']');
        if (field.tagName === 'SELECT') { field.selectedIndex = 0; } else { field.value = field.name.endsWith('[quantity]') ? 1 : ''; }
    });
    invoiceLines.appendChild(newLine);
    invoiceLineIndex++;
});
invoiceLines?.addEventListener('click', function (event) {
    if (event.target.matches('.remove-line') && invoiceLines.querySelectorAll('.invoice-line').length > 1) { event.target.closest('.invoice-line').remove(); }
    updateInvoiceTotals();
});
function updateInvoiceTotals() {
    if (!invoiceLines) { return; }
    let subtotal = 0;
    invoiceLines.querySelectorAll('.invoice-line').forEach(function (line) {
        const quantity = Number(line.querySelector('input[name$="[quantity]"]').value || 0);
        const unitPrice = Number(line.querySelector('input[name$="[unit_price]"]').value || 0);
        const lineTotal = quantity * unitPrice;
        line.querySelector('.document-line-total').textContent = lineTotal.toFixed(2);
        subtotal += lineTotal;
    });
    const rate = Number(document.querySelector('input[name="tax_rate"]')?.value || 0);
    const tax = Math.round(subtotal * rate) / 100;
    document.getElementById('invoiceSubtotal').textContent = subtotal.toFixed(2);
    document.getElementById('invoiceTax').textContent = tax.toFixed(2);
    document.getElementById('invoiceGrandTotal').textContent = (subtotal + tax).toFixed(2);
}
invoiceLines?.addEventListener('change', function (event) {
    if (!event.target.matches('.invoice-item-select')) { return; }
    const selected = event.target.selectedOptions[0];
    const line = event.target.closest('.invoice-line');
    const description = line.querySelector('.invoice-description');
    const price = line.querySelector('input[name$="[unit_price]"]');
    if (selected.value && description.readOnly) { description.value = selected.dataset.name; price.value = selected.dataset.price; }
    updateInvoiceTotals();
});
invoiceLines?.addEventListener('input', updateInvoiceTotals);
document.querySelector('input[name="tax_rate"]')?.addEventListener('input', updateInvoiceTotals);
updateInvoiceTotals();
const serviceOrderSelector = document.getElementById('invoiceServiceOrder');
const productSection = document.getElementById('invoiceProductSection');
const serviceOrderHint = document.getElementById('invoiceOrderHint');
function toggleInvoiceType() {
    if (!serviceOrderSelector || !productSection || !serviceOrderHint) { return; }
    const isServiceOrderInvoice = Boolean(serviceOrderSelector.value);
    productSection.style.display = isServiceOrderInvoice ? 'none' : 'block';
    productSection.querySelectorAll('select,input').forEach(function (field) { field.disabled = isServiceOrderInvoice; });
    if (invoiceAddButton) { invoiceAddButton.style.display = isServiceOrderInvoice ? 'none' : 'inline-flex'; }
    serviceOrderHint.style.display = isServiceOrderInvoice ? 'block' : 'none';
}
serviceOrderSelector?.addEventListener('change', toggleInvoiceType);
toggleInvoiceType();
</script>@endif
@if($page==='order_detail' && !$orderHasInvoice && !in_array($order->status, ['Entregado', 'Cancelado'], true))<script>
const orderChargeDialog = document.getElementById('orderChargeDialog');
const orderChargeForm = document.getElementById('orderChargeForm');
const orderChargeType = document.getElementById('orderChargeType');
const orderProductField = document.getElementById('orderProductField');
const orderServiceField = document.getElementById('orderServiceField');
const orderChargeProduct = document.getElementById('orderChargeProduct');
const orderChargeDescription = document.getElementById('orderChargeDescription');
const orderChargePrice = document.getElementById('orderChargePrice');
const orderChargeQuantity = document.getElementById('orderChargeQuantity');
const orderChargeMethod = document.getElementById('orderChargeMethod');
const editingProductName = document.getElementById('editingProductName');
function setOrderChargeType() {
    const isProduct = orderChargeType.value === 'product';
    orderProductField.style.display = isProduct ? 'block' : 'none';
    orderServiceField.style.display = isProduct ? 'none' : 'block';
    document.getElementById('orderServicePriceField').style.display = isProduct ? 'none' : 'block';
    orderChargeProduct.disabled = !isProduct || Boolean(orderChargeMethod.value);
    orderChargeProduct.required = isProduct && !orderChargeMethod.value;
    orderChargeDescription.disabled = isProduct;
    orderChargeDescription.required = !isProduct;
    orderChargePrice.disabled = isProduct;
}
document.getElementById('openOrderChargeDialog')?.addEventListener('click', function () {
    orderChargeForm.action = orderChargeType.value === 'product' ? orderChargeForm.dataset.productUrl : orderChargeForm.dataset.serviceUrl;
    orderChargeMethod.value = '';
    orderChargeForm.reset();
    orderChargeMethod.value = '';
    document.getElementById('orderChargeTitle').textContent = 'Agregar cargo';
    editingProductName.hidden = true;
    orderChargeProduct.hidden = false;
    setOrderChargeType();
    orderChargeDialog.showModal();
});
orderChargeType.addEventListener('change', setOrderChargeType);
orderChargeType.addEventListener('change', function () {
    if (!orderChargeMethod.value) {
        orderChargeForm.action = orderChargeType.value === 'product' ? orderChargeForm.dataset.productUrl : orderChargeForm.dataset.serviceUrl;
    }
});
document.querySelectorAll('.edit-order-charge').forEach(function (button) {
    button.addEventListener('click', function () {
        const isProduct = button.dataset.kind === 'product';
        orderChargeForm.action = button.dataset.updateUrl;
        orderChargeMethod.value = 'PATCH';
        orderChargeType.value = button.dataset.kind;
        orderChargeQuantity.value = button.dataset.quantity;
        document.getElementById('orderChargeTitle').textContent = 'Editar cargo';
        if (isProduct) {
            orderChargeProduct.hidden = true;
            editingProductName.textContent = button.dataset.name;
            editingProductName.hidden = false;
        } else {
            orderChargeProduct.hidden = false;
            orderChargeDescription.value = button.dataset.name;
            orderChargePrice.value = button.dataset.price;
            editingProductName.hidden = true;
        }
        setOrderChargeType();
        orderChargeDialog.showModal();
    });
});
document.getElementById('closeOrderChargeDialog')?.addEventListener('click', function () { orderChargeDialog.close(); });
setOrderChargeType();
</script>@endif
</body></html>
